struct segtree {
    const static int INF = 1e18; 
    int l, r, v = 0, lz = 0; 
    segtree *lc, *rc; 
    segtree* getmem(); 
    segtree() : segtree(-1, -1) {}; 
    segtree(int l, int r) : l(l), r(r) {
        if (l==r) return; 
        int m=(l+r)/2; 
        lc=getmem(); *lc=segtree(l,m); 
        rc=getmem(); *rc=segtree(m+1,r); 
    }
    int getv() {
        return v+lz; 
    }
    int op(int a, int b) {
        return min(a,b); 
    }
    void upd(int i, int x) {
        add(i,i,x-q(i,i)); 
    }
    void add(int ql, int qr, int x) {
        if (r<ql||qr<l) return; 
        if (ql<=l&&r<=qr) {lz+=x; return;}
        lc->add(ql,qr,x); rc->add(ql,qr,x); 
        v=op(lc->getv(), rc->getv()); 
    }
    int q(int ql, int qr) {
        if (qr<l||r<ql) return INF; 
        if (ql<=l&&r<=qr) return getv(); 
        return op(lc->q(ql,qr), rc->q(ql,qr))+lz; 
    }
};
segtree mem[1000000]; int memsz=0; 
segtree* segtree::getmem() {
    return &mem[memsz++]; 
}

void solve() {
    int n; cin >> n;
    vector<int> v(n);
    unordered_map<int,int> m; 
    segtree st(0,n+2); 
    int i = 0; 
    st.upd(0,-1); 
    for (int &r:v) {
        cin >> r; 
        if (m[r]||r>i) {
            st.add(0,(r-1)/2,1); 
        } 
        else {
            st.upd(r,1e9); 
            st.add(0,r,1); 
        }
        m[r]++; 
        while (1) {
        // for (int j = 0; j < n; j++) cout << st.q(j,j) << " "; cout << "\n"; 
            if (st.q(0,i)<0) break; 
            i++; 
            st.add(0,i,-1); 
            if (m[i]) {
                st.upd(i,1e9); 
                st.add(0,(i-1)/2,-1); 
                st.add(0,i,1); 
            }
        }
        cout << i << " "; //cout << '\n'; 
    }
    cout << "\n"; 
}

int32_t main() {
    ios::sync_with_stdio(0); cin.tie(0);
    int t=1; cin >> t;
    while (t--) solve(); 
}

#include<bits/stdc++.h>
using namespace std;

#define ll long long
const ll mod = 998'244'353;

ll power(ll x, ll y, ll z = LLONG_MAX){
    ll res = 1;
    while(y > 0){
        if(y % 2) res = (res * x) % z;
        y /= 2;
        if(y) x = (x * x) % z;
    }
    return res % z;
}

#define MX 2'000'007
ll fac[MX + 1], numInv[MX + 1], facNumInv[MX + 1];

void compfac(ll z){
    facNumInv[0] = facNumInv[1] = numInv[0] = numInv[1] = fac[0] = 1;
    for(ll i = 2; i <= MX; i++) numInv[i] = numInv[z % i] * (z - z / i) % z;
    for(ll i = 2; i <= MX; i++) facNumInv[i] = (facNumInv[i - 1] * numInv[i]) % z;
    for(ll i = 1; i <= MX; i++) fac[i] = (fac[i - 1] * i) % z;
    return;
}

ll nPrmod(ll n, ll r, ll z){
    if(r > n) return 0;
    return (fac[n] * facNumInv[n - r]) % z;
}

int main(){

    ios_base::sync_with_stdio(false); cin.tie(NULL);

    int t;
    cin >> t;
    compfac(mod);

    while(t--){
        ll n, q;
        cin >> n >> q;

        ll val = (n - 2) * (n - 1);
        val /= 2;
        val %= mod;

        val *= power(2, mod - 2, mod);
        val %= mod;

        vector<ll> cnt(n + 1, 0);
        for(ll i = 1; i <= n; i++) cnt[gcd(i, n)]++;
        cnt[0] = n;

        vector<ll> a(n, 0);
        vector<ll> cur(n + 1, 0);
        cur[0] = n - 1;

        ll zerocnt = 0;
        ll prod = 1;

        ll sum = n * (n - 1);
        sum /= 2;
        sum %= mod;

        while(q--){
            ll i, x;
            cin >> i >> x;
            --i;
            assert(n % x == 0);
            assert(a[i] == 0);

            cur[a[i]]--;

            a[i] = x;
            if(x == n) sum = n - 1 - i, cur[0]++;
            else if(cur[n] == 0) sum -= (n - i - 1);

            if(cur[0] < 0) zerocnt = 1;

            ll prev = nPrmod(cnt[a[i]], cur[a[i]], mod);
            prod *= power(prev, mod - 2, mod);
            prod %= mod;

            cur[a[i]]++;

            ll after = nPrmod(cnt[a[i]], cur[a[i]], mod);
            prod *= after;
            prod %= mod;

            if(cur[a[i]] > cnt[a[i]]) zerocnt = 1;

            ll mul = 1;
            if(cur[n] == 0) mul = cur[0] + 1;

            if(zerocnt > 0) cout << 0 << '\n';
            else cout << ((prod * fac[cur[0]]) % mod * (val * mul % mod + sum)) % mod << '\n';
        }
    }

    return 0;
}

