vector<int> manacher_odd(vector<int> s) {
    int n = s.size();
    s.insert(s.begin(),-2); 
    s.push_back(-3); 
    vector<int> p(n + 2);
    int l = 0, r = 1;
    for(int i = 1; i <= n; i++) {
        p[i] = min(r - i, p[l + (r - i)]);
        while(s[i - p[i]] == s[i + p[i]]) {
            p[i]++;
        }
        if(i + p[i] > r) {
            l = i - p[i], r = i + p[i];
        }
    }
    return vector<int>(begin(p) + 1, end(p) - 1);
}

vector<int> manacher(vector<int> s) {
    vector<int> t;
    for(auto c: s) {
        t.push_back(-1);
        t.push_back(c); 
    }
    t.push_back(-1); 
    auto res = manacher_odd(t);
    return vector<int>(begin(res) + 1, end(res) - 1);
}

struct node {
    int count = 0; 
    unordered_map<int, node> m; 
    node() {
        count = 0; 
    }
};

void add(node &current, vector<int> &a, int d) {
    current.count++; 
    if (d>=a.size()) return; 
    if (current.m.find(a[d])!=current.m.end()) {
        add(current.m[a[d]],a,d+1);
    }
    else {
        node h;
        current.m[a[d]]=h; 
        add(current.m[a[d]],a,d+1); 
    }
}

const int mod = 998244353, MX=1e6+4; 
int F[MX]; 
unordered_map<int,int> counts; 

void init() {
    F[0]=1;
    for (int i = 1; i < MX; i++) F[i]=F[i-1]*i%mod; 
}

int pw(int b, int e=mod-2) {
    int x=1;
    while (e) {
        if (e%2) x=x*b%mod;
        b=b*b%mod;
        e/=2;
    }
    return x; 
}

void dfs(node &current, int cur, int d) {
    if (!d) {
        counts[cur]++;
        return; 
    }
    else (counts[cur]+=F[d-1]*(d-current.m.size()))%=mod; 
    for (auto [i, n]:current.m) {
        dfs(n, cur+n.count, d-1); 
    }
}

void solve() {
    int n, m; cin >> n >> m; 
    vector<int> v(n);
    for (int &r:v) cin >> r; 
    auto t=manacher(v); 
    // for (int r:t) cout << r << " "; cout << "\n"; 
    int cur=0;
    vector<int> prev(m+1,n), nxt(n); 
    for (int i = n-1; ~i; i--) {
        nxt[i]=prev[v[i]];
        prev[v[i]]=i; 
    }
    node head; 
    for (int i = 1; i < n; i++) {
        int k=t[2*i-1]/2;
        cur+=k;  
        if (k<n-i) continue; 
        vector<int> a; 
        for (int j = i-(n-i)-1; j >= 0; j--) {
            if (nxt[j]<=i-(n-i)-1) break;
            a.push_back(v[j]); 
        }
        add(head,a,0); 
    }
    vector<int> a; 
    for (int j = n-1; ~j; j--) {
        if (nxt[j]<n) break;
        a.push_back(v[j]);
    }
    add(head,a,0); 
    counts.clear(); 
    dfs(head,cur,m); 
    int ans=0;
    for (auto [i,c]:counts) {
        // cout << i << " " << c << "\n"; 
        ans=(ans+pw(c,i+1))%mod;
    }
    cout << ans << "\n"; 
}

int32_t main() {
    ios::sync_with_stdio(0); cin.tie(0);
    init(); 
    int t=1; cin >> t;
    while (t--) solve(); 
}
